/// <summary>
/// METCPIRepricingController
/// Controller class for initiating the CPI-driven Sales Order repricing batch job.
/// Manages execution flow, service binding, and duplicate job prevention.
/// </summary>
class METCPIRepricingController extends SysOperationServiceController
{

}

Method.Source:
/// <summary>
/// Initializes the controller by binding it to the repricing service and process method.
/// </summary>
protected void new()
{
    super(classstr(METCPIRepricingService), methodstr(METCPIRepricingService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Provides the default caption for the CPI repricing batch job.
/// </summary>
/// <returns>The batch job caption string.</returns>
protected ClassDescription defaultCaption()
{
    return "@MET:CPISOPricing";
}

/// <summary>
/// Entry point for starting the CPI repricing batch job.
/// Ensures that no duplicate job is currently executing before initiating a new run.
/// Displays a confirmation dialog to the user prior to execution.
/// </summary>
/// <param name="_args">Arguments passed to the batch job.</param>
public static void main(Args _args)
{
    METCPIRepricingController controller = new METCPIRepricingController();

    controller.parmArgs(_args);

    Batch batch;

    select firstonly RecId from batch
        where batch.ClassNumber == classNum(METCPIRepricingController)
          && batch.Status == BatchStatus::Executing;

    if (batch.RecId)
    {
        warning("@MET:BatchWarningCPI");
    }
    else
    {
        if (Box::okCancel("@MET:RepricingWarning", DialogButton::Cancel) == DialogButton::Ok)
        {
              controller.startOperation();
        }
    }
}
